tools.args:
{"command":"$j = Get-Content "$env:TEMP\cua_uia_chrome.json" -Raw | ConvertFrom-Json
"window: $($j.window_title) | total_elements=$($j.total_element_count) | returned=$($j.returned_element_count) | complete=$($j.elements_complete)"
$i = 0
$j.elements | Where-Object { $_.role -eq 'TabItem' } | ForEach-Object { $i++; "$i`t$($_.name)`t[$($_.selected)]`t$($_.bounds | ConvertTo-Json -Compress)" }
"---- Edit ----"
$j.elements | Where-Object { $_.role -eq 'Edit' } | ForEach-Object { "name=$($_.name) | value=$($_.value) | actions=$($_.actions -join ',')" }","description":"Названия вкладок Chrome и значение адресной строки"}

{"command":"$pids = (Get-Process chrome -ErrorAction SilentlyContinue).Id
Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $pids -contains $_.OwningProcess } | ForEach-Object { "port=$($_.LocalPort) addr=$($_.LocalAddress) pid=$($_.OwningProcess)" }
"--- all localhost listeners (any owner) ---"
Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.LocalAddress -in @('127.0.0.1','::1') } | ForEach-Object { "port=$($_.LocalPort) pid=$($_.OwningProcess)" } | Sort-Object -Unique","description":"Проверка CDP-портов Chrome"}
